남은 = 0
with open("용돈.txt") as 파일:
    for 줄 in 파일:
        칸 = 줄.strip().split(",")
        if 칸[0] == "들어옴":
            남은 += int(칸[1])
        else:
            남은 -= int(칸[1])
print("남은 돈", 남은)

표 = {}
with open("투표.txt") as 파일:
    for 줄 in 파일:
        이름 = 줄.strip()
        if 이름 in 표:
            표[이름] += 1
        else:
            표[이름] = 1
일등 = ""
많은 = 0
with open("결과.txt", "w") as 파일:
    for 이름 in 표:
        print(이름, 표[이름], sep=",", file=파일)
        if 표[이름] > 많은:
            일등 = 이름
            많은 = 표[이름]
print("1등", 일등, str(많은) + "표")
